#!/usr/bin/env bash
# Generated by pivota-spec init-dev-server
# Catalog entry: agent-synthesized
# Generator version: init-dev-server@1
#
# Edits ABOVE the END PIVOTA PREAMBLE marker are reset on regen.
# Edits BELOW the marker are preserved on regen.
#
# Why these choices (decision-trace; do not delete):
#   - `set -euo pipefail` not just `-e` — RESEARCH.md Pitfall 4 (silent pipe failures).
#   - `sha256sum` for lockfile hashing — RESEARCH.md "Don't hand-roll" (universal
#     coreutils, no extra dep vs blake3 / git hash-object / md5sum).
#   - Backoff 1s / 2s / 4s — Claude's Discretion per CONTEXT.md (small base, predictable).
#   - Log destination `/tmp/pivota-dev.log` — Open Question #4 resolved (always
#     writable inside Daytona sandboxes; matches existing convention).
#   - Lockfile-sentinel skip combined with INSTALL_PRESENCE_CHECK — RESEARCH.md
#     Pitfall 6 (sentinel survives reboots but install output dirs may not on
#     fresh tmpfs; never skip on a clean directory).
#   - Retry exits with INNER command's last exit code (not a fixed 1) so callers
#     can disambiguate failures from the wrapper.
#   - run_install has an npm ERESOLVE fallback (--legacy-peer-deps) + a FATAL
#     marker (D-12.1) — a scaffold with a lagging peer range must not silently
#     leave node_modules empty and hang the preview on "Waiting to bind".
#   - Agent-synthesized: multi-match (react-next + compose). This project uses
#     Next.js 16 for native dev (port 4000) with a compose-managed PostgreSQL DB.
#     The compose file's `app` service builds for production; dev runs natively.
#     Strategy: start only the DB service via compose, then npm ci + migrate + seed
#     + next dev. Migrate runs AFTER npm ci so node_modules/tsx is present.

set -euo pipefail

# === Bash version guard (RESEARCH.md Pitfall 8) ===
# `wait -n` (used by the multi-process variant) requires bash >= 4.3.
# Fail fast with a clear message; do not silently degrade.
if (( BASH_VERSINFO[0] < 4 )) || { (( BASH_VERSINFO[0] == 4 )) && (( BASH_VERSINFO[1] < 3 )); }; then
  echo "[pivota] bash 4.3+ required for 'wait -n'; found ${BASH_VERSION}" >&2
  exit 127
fi

# === Single-instance guard ===
# Multiple platform paths can invoke the wrapper concurrently (sandbox setup,
# preview open, verify pre-flight) — observed as two `docker compose up --build`
# trees racing in one sandbox. Second invocation exits 0 quietly: the first
# boot is authoritative and callers poll the port, not this process.
exec 200>/tmp/pivota-dev.lock
if ! flock -n 200; then
  echo "[pivota] start-dev.sh already running (lock held) — exiting; poll the ready port instead" >&2
  exit 0
fi

# === D-11.4: tee stdout/stderr to /tmp/pivota-dev.log AND pass through ===
# Researcher resolved log destination: /tmp/pivota-dev.log (always writable,
# matches existing convention). SSE chat panel sees output live AND a file
# exists for scrollback / replay.
mkdir -p /tmp
exec > >(tee -a /tmp/pivota-dev.log) 2>&1
echo "[pivota] $(date -Iseconds) start-dev.sh begin (catalog: agent-synthesized)"

# === D-11.1 + D-11.2: per-stack 0.0.0.0 binding + host allowlist relaxation ===
# Next.js honors HOSTNAME for the dev server bind address since v13.
# CITED: nextjs.org/docs/app/api-reference/config/next-config-js
# HOST=0.0.0.0 is exported for downstream tools that read $HOST.
# allowedDevOrigins is already declared in next.config.ts — no overlay needed.
export HOSTNAME=0.0.0.0
export HOST=0.0.0.0
# NODE_ENV stays unset / development so devDependencies build tools are available
# and Next.js dev mode is active (runtime-environment.md §4).

# === D-11.3: .env.example -> .env seed (platform-injection-safe) ===
# Seed .env from .env.example for first boot, but NEVER let an .env.example
# placeholder shadow a variable the platform already injected into the sandbox
# environment. The motivating bug: .env.example shipped a dead
# `DATABASE_URL=postgresql://user:pass@localhost/...` that overrode the injected
# sidecar DATABASE_URL, so Prisma `db push`/`$connect()` failed. Any KEY already
# set in the environment (DATABASE_URL, POSTGRES_*/MYSQL_*, REDIS_URL, PIVOTA_*,
# plus PORT/NODE_ENV from the preamble above) is dropped from the copy so the
# injected value wins. See references/runtime-environment.md §3.
if [[ ! -f .env && -f .env.example ]]; then
  echo "[pivota] seeding .env from .env.example (preserving platform-injected vars)"
  while IFS= read -r line || [[ -n "$line" ]]; do
    trimmed="${line#"${line%%[![:space:]]*}"}"   # left-trim for the test only
    if [[ "$trimmed" == \#* || -z "$trimmed" || "$trimmed" != *"="* ]]; then
      printf '%s\n' "$line"; continue            # keep comments / blanks / non-assignments
    fi
    key="${trimmed#export }"; key="${key%%=*}"; key="${key//[[:space:]]/}"
    if [[ -n "${!key+x}" ]]; then
      printf '# [pivota] %s omitted — provided by platform environment\n' "$key"
      continue
    fi
    # D-11.5: sanitize the copied assignment. Documented .env.example files
    # column-align inline `# comments` after values, and docker compose's .env
    # parser passes those through as part of the value (motivating bug:
    # `LDAP_URL=   # LDAP server URL, e.g. ldap://...` made a Spring app treat
    # LDAP as enabled and crash-loop on boot, so the compose frontend behind a
    # `service_healthy` dependency never started). Strip them from unquoted
    # values only — a `#` inside quotes is part of the value.
    if [[ "$line" != *\"* && "$line" != *\'* ]]; then
      line="$(printf '%s' "$line" | sed -E 's/[[:space:]]+#.*$//')"
    fi
    # Replace CHANGE_ME placeholder secrets with generated values. Placeholders
    # are landmines at runtime, not just cosmetics: jjwt hard-rejects HMAC keys
    # under 256 bits, so `JWT_SECRET=CHANGE_ME_BASE64_256BIT_SECRET` (240 bits)
    # 500s every login. Same generated value is seen by every compose service
    # reading this .env, so cross-service credentials stay consistent.
    value="${line#*=}"
    value_lc="$(printf '%s' "$value" | tr '[:upper:]' '[:lower:]')"
    if [[ "$value_lc" == change_me* || "$value_lc" == changeme* ]]; then
      generated="$(head -c 48 /dev/urandom | base64 | tr -dc 'A-Za-z0-9')"
      printf '%s=%s\n' "$key" "${generated:0:48}"
      echo "[pivota] generated random value for placeholder $key" >&2
    else
      printf '%s\n' "$line"
    fi
  done < .env.example > .env
fi

# === Pre-exec: start compose DB service (db) and wait for it to be healthy ===
# This project uses a compose-managed PostgreSQL DB. The app service in the
# compose file builds for production (NODE_ENV=production Dockerfile build) and
# is NOT used here — we run Next.js natively in dev mode for faster iteration.
# Only the `db` service is started via compose; the app service is excluded.
# DB_SENTINEL guards this so a sandbox reboot doesn't re-wait on an already-up DB.
DB_SENTINEL="/tmp/pivota-db-started"
if [[ ! -f "$DB_SENTINEL" ]]; then
  echo "[pivota] starting compose db service..."
  docker compose up -d db
  echo "[pivota] waiting for db service to be healthy (up to 60s)..."
  DB_HEALTHY=0
  for i in $(seq 1 12); do
    STATUS=$(docker compose ps --format json db 2>/dev/null | python3 -c "import sys,json; data=sys.stdin.read().strip(); rows=json.loads(data) if data.startswith('[') else [json.loads(l) for l in data.splitlines() if l.strip()]; print(rows[0].get('Health','') if rows else '')" 2>/dev/null || echo "")
    if [[ "$STATUS" == "healthy" ]]; then
      DB_HEALTHY=1
      break
    fi
    echo "[pivota] db health: ${STATUS:-unknown} (attempt $i/12)"
    sleep 5
  done
  if [[ "$DB_HEALTHY" == "0" ]]; then
    echo "[pivota] WARN db service did not reach healthy in 60s — proceeding anyway (migrate may retry)" >&2
  else
    echo "[pivota] db service is healthy"
  fi
  touch "$DB_SENTINEL"
else
  echo "[pivota] db sentinel present — assuming db service already running"
fi

# === D-12: idempotent install via lockfile hash + presence check ===
SENTINEL="/tmp/pivota-setup-sentinel"
LOCK_FILE_PATH="package-lock.json"
INSTALL_PRESENCE_CHECK="node_modules"
INSTALL_CMD='npm ci || npm install'

run_install() {
  echo "[pivota] running install: $INSTALL_CMD"
  local rc=0
  bash -c "$INSTALL_CMD" || rc=$?   # capture directly; `if ...; then` would reset $? to 0 on the no-else path
  if (( rc == 0 )); then
    return 0
  fi
  # D-12.1: npm peer-dependency (ERESOLVE) fallback + loud failure.
  # A fresh scaffold can pin a transitive lib whose peer range lags the
  # project's react/next major (observed: react-leaflet@4 wants react@18 under
  # a react@19 project). npm 7+ aborts `npm ci`/`npm install` with ERESOLVE and
  # writes NO node_modules — so EXEC_CMD below never binds a port and the
  # preview panel hangs on "Waiting for dev server to bind..." with no surfaced
  # error. Retry once with --legacy-peer-deps so boot can proceed, but log
  # LOUDLY: a force-resolved peer range can install a runtime-incompatible tree
  # (the offending component may crash when rendered — surface it at UAT).
  if [[ "$INSTALL_CMD" == *"npm "* ]]; then
    echo "[pivota] WARN install failed (exit=$rc) — retrying with --legacy-peer-deps (peer conflict force-resolved; runtime incompatibility possible)"
    local rc2=0
    npm install --legacy-peer-deps || rc2=$?
    if (( rc2 == 0 )); then
      echo "[pivota] WARN install succeeded via --legacy-peer-deps fallback — a dependency's peer range is unsatisfied; fix package.json (this is a real bug, not just a warning)"
      return 0
    fi
    rc=$rc2
  fi
  # Emit a greppable marker so the platform surfaces "install failed" instead of
  # letting the dev server silently never bind. `set -e` still aborts the script.
  echo "[pivota] FATAL install failed (exit=$rc) — dev server cannot start; resolve the dependency conflict in the manifest" >&2
  return "$rc"
}

if [[ -n "$LOCK_FILE_PATH" && -f "$LOCK_FILE_PATH" ]]; then
  CURRENT_HASH=$(sha256sum "$LOCK_FILE_PATH" | cut -d' ' -f1)
  PREVIOUS_HASH=$(cat "$SENTINEL" 2>/dev/null || echo "")

  # RESEARCH.md Pitfall 6: lockfile-unchanged is necessary but not sufficient —
  # the install-output directory must also exist (sentinel survives but
  # node_modules / .venv / target might not on a fresh sandbox tmpfs).
  PRESENCE_OK=1
  if [[ -n "$INSTALL_PRESENCE_CHECK" && ! -e "$INSTALL_PRESENCE_CHECK" ]]; then
    PRESENCE_OK=0
  fi

  if [[ "$CURRENT_HASH" == "$PREVIOUS_HASH" && "$PRESENCE_OK" == "1" ]]; then
    echo "[pivota] lockfile unchanged AND install output present; skipping install"
  else
    if [[ "$PRESENCE_OK" == "0" ]]; then
      echo "[pivota] install output ($INSTALL_PRESENCE_CHECK) missing; install required"
    else
      echo "[pivota] lockfile changed (or first boot); install required"
    fi
    run_install
    echo "$CURRENT_HASH" > "$SENTINEL"
  fi
elif [[ -n "$INSTALL_CMD" ]]; then
  # No lockfile to compare; honor any sentinel mismatch by running install once per sandbox.
  if [[ ! -f "$SENTINEL" ]]; then
    run_install
    touch "$SENTINEL"
  fi
fi

# === Post-install: DB migrate + seed ===
# Migrate runs AFTER npm ci so node_modules/.bin/tsx (drizzle-kit, tsx) is present.
# Never assume host CLIs like psql exist — run via the project's own tooling.
# Non-fatal: a transient DB hiccup at generation time must not strand boot;
# the app will error on data requests rather than failing to start.
MIGRATE_SENTINEL="/tmp/pivota-migrate-sentinel"
if [[ ! -f "$MIGRATE_SENTINEL" ]]; then
  echo "[pivota] running DB migrate (tsx drizzle/migrate.ts)..."
  DATABASE_URL="${DATABASE_URL:-postgres://assessmentform:assessmentform_dev_password@localhost:5432/assessmentform}" \
    ./node_modules/.bin/tsx drizzle/migrate.ts 2>&1 \
    || echo "[pivota] WARN db:migrate exited non-zero — app may boot onto an unmigrated DB; check /tmp/pivota-dev.log"
  echo "[pivota] running DB seed (tsx drizzle/seed.ts)..."
  DATABASE_URL="${DATABASE_URL:-postgres://assessmentform:assessmentform_dev_password@localhost:5432/assessmentform}" \
    ./node_modules/.bin/tsx drizzle/seed.ts 2>&1 \
    || echo "[pivota] WARN db:seed exited non-zero — continuing"
  touch "$MIGRATE_SENTINEL"
else
  echo "[pivota] migrate sentinel present — skipping migrate+seed (already ran this sandbox)"
fi

# === D-14: retry loop (3 attempts, exponential backoff 1s / 2s / 4s) ===
# Final-attempt exit code propagates the INNER command's exit code, not a
# fixed 1, so the caller (platform / Daytona) can distinguish "wrapper bug"
# from "user command failed with N".
# Use package.json dev script to honor user-declared port (4000) and flags.
EXEC_CMD='npm run dev'
ATTEMPT=1
DELAY=1
while (( ATTEMPT <= 3 )); do
  echo "[pivota] attempt $ATTEMPT: $EXEC_CMD"
  if bash -c "$EXEC_CMD"; then
    echo "[pivota] inner command exited 0; propagating success"
    exit 0
  fi
  EXIT_CODE=$?
  if (( ATTEMPT == 3 )); then
    echo "[pivota] all 3 attempts failed (last exit=$EXIT_CODE); surfacing failure"
    exit "$EXIT_CODE"
  fi
  echo "[pivota] attempt $ATTEMPT failed (exit=$EXIT_CODE); retrying in ${DELAY}s"
  sleep "$DELAY"
  DELAY=$(( DELAY * 2 ))
  ATTEMPT=$(( ATTEMPT + 1 ))
done

# Unreachable, but keep for analyzer happiness
exit 1
# === END PIVOTA PREAMBLE ===
